"""Procedural synthetic sensor streams for replay tests. PURE. No CAD and no course file: a world is a
handful of axis-aligned boxes plus the floor, generated by the test.

Messages are SimpleNamespace objects shaped like the ROS ones (header.stamp.sec/nanosec, etc.), so they
pass through exactly the same adapters as live or bagged data. Defaults mirror the 2026-11-07 bag where
measured (odometry 30 Hz, state 5 Hz, camera_info 30 Hz, 320x200 intrinsics, the base_link->camera TF
chain); depth rate and latency are NOT measured on the drone (no depth image was recorded), so the
defaults (15 Hz, 0.08 s) are assumptions to vary.
"""
from __future__ import annotations

import json
import math
from dataclasses import dataclass, field
from types import SimpleNamespace as NS
from typing import Callable, List, Optional, Sequence, Tuple

import numpy as np

from .observation import rot_from_quat_xyzw
from .transforms import StaticTransformTree, validate_extrinsic

BAG_K = (198.3984, 198.4348, 162.4510, 101.9492)       # /oak/stereo/camera_info, 2026-11-07 bag
BAG_W, BAG_H = 320, 200
CAM_FRAME = "oak_rgb_camera_optical_frame"
BAG_TF = [("base_link", "oak_parent_frame", (0.1053, 0.0, 0.0304), (0, 0, 0, 1)),
          ("oak_parent_frame", "oak", (0, 0, 0), (0, 0, 0, 1)),
          ("oak", "oak_rgb_camera_frame", (0, 0, 0), (0, 0, 0, 1)),
          ("oak_rgb_camera_frame", CAM_FRAME, (0, 0, 0), (-0.5, 0.5, -0.5, 0.5))]


def bag_tree() -> StaticTransformTree:
    tr = StaticTransformTree()
    for p, c, t, q in BAG_TF:
        tr.add(p, c, t, q)
    return tr


def bag_extrinsic():
    R, t = bag_tree().lookup("base_link", CAM_FRAME)
    return validate_extrinsic(CAM_FRAME, R, t)[0]


def stamp_ns(t: float):
    sec, ns = divmod(int(round(t * 1e9)), 1_000_000_000)
    return NS(sec=sec, nanosec=ns)


def quat_from_rpy(roll, pitch, yaw):
    cr, sr, cp, sp, cy, sy = (math.cos(roll / 2), math.sin(roll / 2), math.cos(pitch / 2), math.sin(pitch / 2),
                              math.cos(yaw / 2), math.sin(yaw / 2))
    return (sr * cp * cy - cr * sp * sy, cr * sp * cy + sr * cp * sy, cr * cp * sy - sr * sp * cy, cr * cp * cy + sr * sp * sy)


def odom_msg(stamp, pos, quat, v_body, pos_var=0.0):
    cov = [0.0] * 36
    cov[0] = cov[7] = cov[14] = pos_var
    return NS(header=NS(stamp=stamp_ns(stamp) if stamp else NS(sec=0, nanosec=0), frame_id="odom"),
              child_frame_id="base_link",
              pose=NS(pose=NS(position=NS(x=pos[0], y=pos[1], z=pos[2]),
                              orientation=NS(x=quat[0], y=quat[1], z=quat[2], w=quat[3])), covariance=cov),
              twist=NS(twist=NS(linear=NS(x=v_body[0], y=v_body[1], z=v_body[2]), angular=NS(x=0.0, y=0.0, z=0.0))))


def info_msg(stamp, K=BAG_K, w=BAG_W, h=BAG_H, frame=CAM_FRAME):
    fx, fy, cx, cy = K
    return NS(header=NS(stamp=stamp_ns(stamp), frame_id=frame), width=w, height=h,
              k=[fx, 0.0, cx, 0.0, fy, cy, 0.0, 0.0, 1.0])


def depth_msg(stamp, depth_m: np.ndarray, frame=CAM_FRAME):
    mm = np.where(np.isfinite(depth_m), np.clip(depth_m * 1000.0, 0, 65535), 0).astype(np.uint16)
    h, w = mm.shape
    return NS(header=NS(stamp=stamp_ns(stamp) if stamp else NS(sec=0, nanosec=0), frame_id=frame),
              height=h, width=w, encoding="16UC1", step=w * 2, data=mm.tobytes())


def state_msg(stamp, armed=True, offboard=False):
    return NS(data=json.dumps({"stamp": stamp, "px4_link": True, "armed": armed, "landed": not armed,
                               "nav_state": 2 if not offboard else 14, "nav_state_name": "POSCTL",
                               "offboard_active": offboard, "clamped": [],
                               "envelope": {"min_altitude_m": 0.3, "max_altitude_m": 3.0, "max_speed_mps": 1.5}}))


Box = Tuple[float, float, float, float, float, float]        # xmin xmax ymin ymax zmin zmax (ENU)


def render_depth(pos, quat, boxes: Sequence[Box], extr=None, K=BAG_K, w=BAG_W, h=BAG_H, floor=True,
                 max_range=8.0) -> np.ndarray:
    """Optical-z depth (metres, NaN = no return) seen from a body pose, by exact ray casting."""
    extr = extr or bag_extrinsic()
    R_wb = rot_from_quat_xyzw(*quat)
    R_wc = R_wb @ extr.R_body_cam
    o = np.asarray(pos, float) + R_wb @ extr.t_body_cam
    fx, fy, cx, cy = K
    vs, us = np.mgrid[0:h, 0:w]
    rays = np.stack([(us - cx) / fx, (vs - cy) / fy, np.ones_like(us, float)], axis=-1).reshape(-1, 3)
    d = rays @ R_wc.T                                  # world direction per unit optical depth
    best = np.full(len(d), np.inf)
    with np.errstate(divide="ignore", invalid="ignore"):
        for b in boxes:
            lo, hi = np.array(b[0::2], float), np.array(b[1::2], float)
            t1, t2 = (lo - o) / d, (hi - o) / d
            tn = np.nanmax(np.minimum(t1, t2), axis=1)
            tf = np.nanmin(np.maximum(t1, t2), axis=1)
            hit = (tf >= np.maximum(tn, 0.0)) & (tn > 0)
            best = np.where(hit & (tn < best), tn, best)
        if floor:
            tz = np.where(d[:, 2] < -1e-9, -o[2] / d[:, 2], np.inf)
            best = np.minimum(best, np.where(tz > 0, tz, np.inf))
    best[best > max_range] = np.nan
    return best.reshape(h, w).astype(np.float32)


@dataclass
class Scenario:
    """Ground-truth motion + world + sensor imperfections -> a list of (rx, kind, msg) events."""
    motion: Callable[[float], Tuple[np.ndarray, float, np.ndarray]]   # t -> (pos ENU, yaw, vel_world)
    boxes: List[Box] = field(default_factory=list)
    duration: float = 6.0
    t0: float = 1_794_095_811.0          # epoch-like start (both clocks), as in the bag
    odom_hz: float = 30.0
    depth_hz: float = 15.0
    state_hz: float = 5.0
    odom_latency: float = 0.08
    depth_latency: float = 0.08
    popup: Optional[Tuple[float, Box]] = None                 # (t_rel, box) appears at t_rel
    depth_corrupt: Optional[Callable[[float, np.ndarray], np.ndarray]] = None
    odom_gaps: List[Tuple[float, float]] = field(default_factory=list)
    depth_gaps: List[Tuple[float, float]] = field(default_factory=list)
    vo_lost: List[Tuple[float, float]] = field(default_factory=list)
    depth_stamp_offset: float = 0.0                           # e.g. -t0: zero-based stamps (time-domain mismatch)
    odom_stamp_offset: float = 0.0
    reorder_depth: bool = False                               # deliver depth frames pairwise swapped
    depth_extra_delay: List[Tuple[float, float, float]] = field(default_factory=list)  # (t0, t1, delay)
    roll_pitch: Callable[[float], Tuple[float, float]] = lambda t: (0.0, 0.0)
    pos_var: Callable[[float], float] = lambda t: 0.0

    def _in(self, t, wins):
        return any(a <= t < b for a, b in wins)

    def events(self):
        ev = []
        n = int(self.duration * self.odom_hz)
        for i in range(n):
            t = i / self.odom_hz
            pos, yaw, vw = self.motion(t)
            r, p = self.roll_pitch(t)
            q = quat_from_rpy(r, p, yaw)
            vb = rot_from_quat_xyzw(*q).T @ np.asarray(vw, float)
            rx = self.t0 + t + self.odom_latency
            if not self._in(t, self.odom_gaps):
                ev.append((rx, "odom", odom_msg(self.t0 + t + self.odom_stamp_offset, pos, q, vb, self.pos_var(t))))
            ev.append((rx, "vo", 2 if self._in(t, self.vo_lost) else 1))
            if i % max(1, int(round(self.odom_hz / 30.0))) == 0:
                ev.append((self.t0 + t + 0.005, "camera_info", info_msg(self.t0 + t)))
        for i in range(int(self.duration * self.state_hz)):
            t = i / self.state_hz
            ev.append((self.t0 + t + 0.01, "state", state_msg(self.t0 + t)))
        depth = []
        for i in range(int(self.duration * self.depth_hz)):
            t = i / self.depth_hz
            if self._in(t, self.depth_gaps):
                continue
            pos, yaw, _ = self.motion(t)
            r, p = self.roll_pitch(t)
            boxes = list(self.boxes) + ([self.popup[1]] if self.popup and t >= self.popup[0] else [])
            img = render_depth(pos, quat_from_rpy(r, p, yaw), boxes)
            if self.depth_corrupt is not None:
                img = self.depth_corrupt(t, img.copy())
            delay = self.depth_latency + sum(d for a, b, d in self.depth_extra_delay if a <= t < b)
            depth.append([self.t0 + t + delay, "depth", depth_msg(self.t0 + t + self.depth_stamp_offset, img)])
        if self.reorder_depth:
            for k in range(0, len(depth) - 1, 2):
                depth[k][0], depth[k + 1][0] = depth[k + 1][0], depth[k][0]
        ev += [tuple(d) for d in depth]
        return ev


def straight(v=0.6, yaw=0.0, start=(0.0, 0.0, 1.0), stop_at: Optional[float] = None):
    """Constant-velocity motion along yaw (optionally coming to rest at distance stop_at)."""
    d = np.array([math.cos(yaw), math.sin(yaw), 0.0])

    def f(t):
        s = v * t if stop_at is None else min(v * t, stop_at)
        moving = stop_at is None or v * t < stop_at
        return np.asarray(start, float) + s * d, yaw, (v * d if moving else np.zeros(3))
    return f
